// Not minified. The .min.js suffix keeps the personal site's jekyll-terser step from rewriting this ES module.
// Linked 3D viewer: several panes (original + edits) share one camera, so dragging or zooming any pane moves all of
// them. All models of one task share one frame (the union of their bounds), so size and position changes stay visible.
// One WebGL canvas per viewer draws every pane with scissor rectangles.
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.min.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.min.js';
import { DRACOLoader } from 'three/addons/loaders/DRACOLoader.min.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.min.js';

const draco = new DRACOLoader();
draco.setDecoderPath(new URL('../lib/three/addons/libs/draco/gltf/', import.meta.url).href);
// The page may ask for the pure-JS decoder (window.SITE_DRACO = 'js') where WebAssembly is not allowed.
if (window.SITE_DRACO) draco.setDecoderConfig({ type: window.SITE_DRACO });
const loader = new GLTFLoader();
loader.setDRACOLoader(draco);
const cache = new Map();   // url -> Promise<gltf.scene>

function loadModel(url) {
  if (!cache.has(url)) cache.set(url, loader.loadAsync(url).then(g => g.scene));
  return cache.get(url).then(s => s.clone(true));
}

function shadowTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const g = c.getContext('2d');
  const grd = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grd.addColorStop(0, 'rgba(20,24,32,0.55)'); grd.addColorStop(0.55, 'rgba(20,24,32,0.18)'); grd.addColorStop(1, 'rgba(20,24,32,0)');
  g.fillStyle = grd; g.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}
let SHADOW = null;

export class LinkedViewer {
  // container: element holding the pane elements; panes are found by `.pane-3d` inside it.
  constructor(container, { az = 38, el = 22, autoRotate = true } = {}) {
    this.container = container;
    this.az = az; this.el = el; this.autoRotateDefault = autoRotate;
    this.canvas = document.createElement('canvas');
    this.canvas.className = 'viewer-canvas';
    container.prepend(this.canvas);
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, alpha: true });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.toneMapping = THREE.AgXToneMapping;
    this.renderer.toneMappingExposure = 1.15;
    this.renderer.setClearColor(0x000000, 0);
    const pmrem = new THREE.PMREMGenerator(this.renderer);
    this.env = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
    this.camera = new THREE.PerspectiveCamera(28, 1, 0.01, 100);
    this.controls = new OrbitControls(this.camera, container);
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.12;
    this.controls.enablePan = false;
    this.controls.rotateSpeed = 0.8;
    this.controls.zoomSpeed = 0.9;
    this.controls.autoRotate = autoRotate;
    this.controls.autoRotateSpeed = 1.1;
    container.style.touchAction = 'pan-y';   // vertical swipes scroll the page on touch screens; horizontal drags rotate
    this.controls.addEventListener('change', () => this.request());
    this.controls.addEventListener('start', () => { this.controls.autoRotate = false; });
    container.addEventListener('dblclick', () => this.resetCamera());
    this.panes = [];
    this.token = 0;
    this.visible = false;
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(container);
    this.io = new IntersectionObserver(es => { this.visible = es[0].isIntersecting; if (this.visible) this.loop(); }, { rootMargin: '100px' });
    this.io.observe(container);
    this.resize();
  }

  // panes: [{el, url, bounds, frame}] where el is the pane element, url the GLB (or null), bounds its {min, max} (Y-up)
  // and frame a key: panes with the same key share one frame (the union of their bounds), so relative size and position
  // stay visible among them. A pane with its own key is scaled to fill the view on its own.
  async show(panes) {
    const token = ++this.token;
    this.panes = panes.map(p => ({ ...p, scene: null }));
    const frames = {};
    for (const p of this.panes) {
      if (!p.bounds) continue;
      const f = frames[p.frame] ||= { lo: [Infinity, Infinity, Infinity], hi: [-Infinity, -Infinity, -Infinity] };
      for (let i = 0; i < 3; i++) { f.lo[i] = Math.min(f.lo[i], p.bounds.min[i]); f.hi[i] = Math.max(f.hi[i], p.bounds.max[i]); }
    }
    let radius = 0;
    for (const f of Object.values(frames)) {
      const size = f.hi.map((h, i) => h - f.lo[i]);
      f.s = 1 / Math.max(...size, 1e-6);
      f.center = f.lo.map((l, i) => (l + f.hi[i]) / 2);
      f.height = size[1] * f.s;
      radius = Math.max(radius, 0.5 * Math.hypot(...size) * f.s);
    }
    const first = this.panes.find(p => p.bounds);
    this.frame = first ? frames[first.frame] : { height: 1 };
    this.frames = frames;
    this.radius = radius || 0.87;
    this.resetCamera(true);
    this.controls.autoRotate = this.autoRotateDefault;
    await Promise.all(this.panes.map(async p => {
      if (!p.url) return;
      p.el.classList.add('is-loading');
      try {
        const obj = await loadModel(p.url);
        if (token !== this.token) return;
        p.scene = this.makeScene(obj, frames[p.frame]);
      } catch (e) {
        p.el.classList.add('is-error');
        console.error('model failed', p.url, e);
      } finally {
        p.el.classList.remove('is-loading');
      }
      this.request();
    }));
  }

  makeScene(obj, frame) {
    const { s, center, lo } = frame;
    const scene = new THREE.Scene();
    scene.environment = this.env;
    scene.environmentIntensity = 0.85;
    const key = new THREE.DirectionalLight(0xffffff, 1.6); key.position.set(2, 4, 3); scene.add(key);
    const rim = new THREE.DirectionalLight(0xffffff, 0.5); rim.position.set(-3, 2, -2); scene.add(rim);
    const root = new THREE.Group();
    root.scale.setScalar(s);
    root.position.set(-center[0] * s, -lo[1] * s - 0.5, -center[2] * s);  // union sits on y = -0.5, centred in x/z
    obj.traverse(o => {
      if (o.isMesh) {
        const m = o.material;
        if (m && m.isMeshStandardMaterial) { m.roughness = Math.max(m.roughness, 0.5); m.metalness = 0; m.side = THREE.DoubleSide; }
      }
    });
    root.add(obj);
    scene.add(root);
    SHADOW = SHADOW || shadowTexture();
    const w = (frame.hi[0] - frame.lo[0]) * s, d = (frame.hi[2] - frame.lo[2]) * s;
    const sh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), new THREE.MeshBasicMaterial({ map: SHADOW, transparent: true, depthWrite: false }));
    sh.rotation.x = -Math.PI / 2; sh.position.y = -0.5 - 0.002; sh.scale.set(w * 1.5 + 0.1, d * 1.5 + 0.1, 1);
    scene.add(sh);
    return scene;
  }

  resetCamera(instant) {
    const r = this.radius || 0.87;
    const fov = THREE.MathUtils.degToRad(this.camera.fov);
    const dist = (r / Math.sin(fov / 2)) * 0.98;
    const az = THREE.MathUtils.degToRad(this.az), el = THREE.MathUtils.degToRad(this.el);
    const ty = (this.frame && this.frame.height != null ? this.frame.height / 2 : 0.5) - 0.5;
    this.controls.target.set(0, ty, 0);
    this.camera.position.set(dist * Math.cos(el) * Math.sin(az), ty + dist * Math.sin(el), dist * Math.cos(el) * Math.cos(az));
    this.controls.minDistance = dist * 0.25;
    this.controls.maxDistance = dist * 3;
    this.camera.near = dist / 100; this.camera.far = dist * 10;
    this.camera.updateProjectionMatrix();
    this.controls.update();
    this.request();
  }

  resize() {
    const w = this.container.clientWidth, h = this.container.clientHeight;
    if (!w || !h) return;
    this.renderer.setSize(w, h, false);
    this.canvas.style.width = w + 'px'; this.canvas.style.height = h + 'px';
    this.request();
  }

  request() { if (!this.pending) { this.pending = true; requestAnimationFrame(() => { this.pending = false; this.render(); }); } }

  loop() {
    if (this.looping) return;
    this.looping = true;
    const tick = () => {
      if (!this.visible) { this.looping = false; return; }
      const moved = this.controls.update();
      if (moved || this.controls.autoRotate) this.render();
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }

  render() {
    const r = this.renderer, cr = this.container.getBoundingClientRect();
    const H = this.container.clientHeight;
    r.setScissorTest(false); r.clear(); r.setScissorTest(true);
    for (const p of this.panes) {
      if (!p.scene) continue;
      const pr = (p.view || p.el).getBoundingClientRect();
      const x = pr.left - cr.left, y = pr.top - cr.top, w = pr.width, h = pr.height;
      if (w < 2 || h < 2) continue;
      r.setViewport(x, H - y - h, w, h); r.setScissor(x, H - y - h, w, h);
      this.camera.aspect = w / h; this.camera.zoom = Math.min(1, w / h);   // a tall pane keeps the horizontal framing of a square one
      this.camera.updateProjectionMatrix();
      r.render(p.scene, this.camera);
    }
  }
}
